import{_ as a,o as r,c as e,a5 as d}from"./chunks/framework.bIR-4glx.js";const p=JSON.parse('{"title":"AI 学习记录：从工具协作到独立能力","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/ai-learning-log.zh.md","filePath":"public/downloads/worksheets/ai-learning-log.zh.md","lastUpdated":1795488252000}'),h={name:"public/downloads/worksheets/ai-learning-log.zh.md"};function i(l,t,n,b,o,s){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="ai-学习记录-从工具协作到独立能力" tabindex="-1">AI 学习记录：从工具协作到独立能力 <a class="header-anchor" href="#ai-学习记录-从工具协作到独立能力" aria-label="Permalink to &quot;AI 学习记录：从工具协作到独立能力&quot;">​</a></h1><p>每次只记录一个可检查的学习切片。AI 生成的摘要、评分和解释不是事实来源；原始材料、自己的首版、实际作品和真实反馈才是证据。不要把学习记录写成“我和模型聊了什么”，而要写成“工具退出后，我还能独立完成什么”。</p><h2 id="_1-任务与起点" tabindex="-1">1. 任务与起点 <a class="header-anchor" href="#_1-任务与起点" aria-label="Permalink to &quot;1. 任务与起点&quot;">​</a></h2><h3 id="ai-learning-log-yyyy-mm-dd" tabindex="-1">AI Learning Log - YYYY-MM-DD <a class="header-anchor" href="#ai-learning-log-yyyy-mm-dd" aria-label="Permalink to &quot;AI Learning Log - YYYY-MM-DD&quot;">​</a></h3><p>真实场景与受众：<br> 本次主问题：<br> 要完成的动作与标准：<br> 材料、版本与来源：<br> 时间、设备和环境限制：<br> 允许的词典 / 翻译 / 搜索 / AI / 人工帮助：<br> 隐私、版权、考试与责任边界：</p><h2 id="_2-无-ai-基线" tabindex="-1">2. 无 AI 基线 <a class="header-anchor" href="#_2-无-ai-基线" aria-label="Permalink to &quot;2. 无 AI 基线&quot;">​</a></h2><p>独立尝试的开始/结束时间：<br> 无 AI 样本位置：<br> 我当时能够解释或完成的内容：<br> 暴露的错误、未知和判断盲点：<br> 当时的信心（0-2）：</p><p>不要先让 AI 写答案再把它叫作起点。若任务本身允许查词或看文档，记录允许的帮助；基线的价值是说明你在这些条件下独立能做什么。</p><h2 id="_3-约定-ai-只做什么" tabindex="-1">3. 约定 AI 只做什么 <a class="header-anchor" href="#_3-约定-ai-只做什么" aria-label="Permalink to &quot;3. 约定 AI 只做什么&quot;">​</a></h2><p>模型 / 版本 / 日期：<br> 本次输入模态：文字 / 音频 / 图片 / 视频 / 混合<br> 实际提供的上下文、检索材料与记忆设置：<br> 任务/运行编号、过程轨迹和检查点位置：<br> 浏览器页面、截图和外部链接是否按不可信输入处理：<br> 网络出口、工具授权和外部写入收据：<br> 使用模式：诊断 / 追问 / 解释 / 反例 / 转写 / 候选 / 其他<br> AI 可以做：<br> AI 不可以做：<br> 传给模型的最小材料：<br> 不会传入的字段或文件：</p><p>每轮只推进一个切片。先让模型指出缺口、假设、来源和不确定性，不先请求整段代做。</p><h2 id="_4-交互与来源核验" tabindex="-1">4. 交互与来源核验 <a class="header-anchor" href="#_4-交互与来源核验" aria-label="Permalink to &quot;4. 交互与来源核验&quot;">​</a></h2><table tabindex="0"><thead><tr><th>回合</th><th>我的问题/动作</th><th>模型建议</th><th>建议类型</th><th>来源/不确定性</th><th>我的决定</th></tr></thead><tbody><tr><td></td><td></td><td></td><td>解释 / 追问 / 候选 / 反馈 / 代码 / 其他</td><td></td><td>采纳 / 部分 / 拒绝 / 待核验</td></tr></tbody></table><p>我核对过的原始来源：<br> 原始录音、图片或视频位置，以及时间段 / 页码 / 图中区域：<br> 转写、识图或引用错误，与我的知识错误分别记录：<br> 我发现的错误、过时或捏造内容：<br> 哪些建议改变了我的理解，为什么：<br> 哪些建议只改变了表面表达：</p><p>来源、事实、权限、隐私和最终判断由人确认。模型说得自信不提高证据等级。</p><h2 id="_5-关闭-ai-后主动产出" tabindex="-1">5. 关闭 AI 后主动产出 <a class="header-anchor" href="#_5-关闭-ai-后主动产出" aria-label="Permalink to &quot;5. 关闭 AI 后主动产出&quot;">​</a></h2><p>关闭 AI 的时间：<br> 独立完成的作品、解释、代码或决定：<br> 独立用时：<br> 仍然需要的提示：<br> 我能否解释每个关键步骤：是 / 部分 / 否<br> 测试、读者/用户反馈或运行结果：</p><h2 id="_6-三次对照" tabindex="-1">6. 三次对照 <a class="header-anchor" href="#_6-三次对照" aria-label="Permalink to &quot;6. 三次对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>样本</th><th>条件</th><th>任务/质量</th><th style="text-align:right;">用时</th><th style="text-align:right;">返工</th><th style="text-align:right;">信心</th><th>证据位置</th></tr></thead><tbody><tr><td>无 AI 基线</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>AI 辅助版</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>延迟独立版（3-7 天）</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr><tr><td>平行任务版（换条件）</td><td></td><td></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td style="text-align:right;"></td><td></td></tr></tbody></table><table tabindex="0"><thead><tr><th>结果</th><th>更谨慎的解释</th></tr></thead><tbody><tr><td>辅助版和独立版都改善</td><td>可能形成了可撤掉的支架，仍需更多迁移</td></tr><tr><td>只有辅助版改善</td><td>成品改善，关键步骤可能被外包</td></tr><tr><td>时间变短但返工增多</td><td>速度换来了速度债</td></tr><tr><td>信心上升但事实/测试下降</td><td>先校准判断，再增加工具权限</td></tr></tbody></table><p>一次对照不能证明因果，但能比“AI 很有用”更清楚地记录工具贡献。</p><h2 id="_7-错误、反馈与迁移" tabindex="-1">7. 错误、反馈与迁移 <a class="header-anchor" href="#_7-错误、反馈与迁移" aria-label="Permalink to &quot;7. 错误、反馈与迁移&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误/缺口</th><th>样本</th><th>类型</th><th>下一次只修什么</th><th>平行任务结果</th></tr></thead><tbody><tr><td></td><td></td><td>事实 / 词汇 / 结构 / 语法 / 策略 / 注意 / 工具依赖</td><td></td><td></td></tr></tbody></table><p>真实读者/用户复述或执行结果：<br> 我采纳、部分采纳、拒绝或延后的反馈及理由：<br> 换主题/受众/模态/时间后仍能完成的动作：<br> 仍然只在原题成功的动作：</p><h2 id="_8-延迟保持与交接" tabindex="-1">8. 延迟保持与交接 <a class="header-anchor" href="#_8-延迟保持与交接" aria-label="Permalink to &quot;8. 延迟保持与交接&quot;">​</a></h2><p>第 1 天：撤掉了什么，独立完成什么：<br> 第 3-7 天：换了什么条件，结果如何：<br> 第 14 天：关闭旧对话后能否解释和使用：<br> 第 30 天：真实任务是否减少猜测或返工：<br> 状态文件位置：<br> 最后一次运行/恢复编号与最终环境状态：<br> 换新会话或另一工具后，能否仅凭状态文件继续：<br> 交接给谁、何时、什么权限：<br> 停止或回滚条件：</p><h2 id="_9-下一周期决定" tabindex="-1">9. 下一周期决定 <a class="header-anchor" href="#_9-下一周期决定" aria-label="Permalink to &quot;9. 下一周期决定&quot;">​</a></h2><p>工具真正帮助的部分：<br> 工具制造的风险或依赖：<br> 我已经拥有的独立能力证据：<br> 仍无证据的结论：<br> 继续 / 降档 / 改变变量 / 暂停 / 求助：<br> 下一项最小任务：<br> 下一次复查日期：</p><p>相关入口：<a href="https://byoungd.github.io/up/threads/part-1/1-understanding" target="_blank" rel="noreferrer">认知篇：把努力变成可验证的学习</a> ｜ <a href="https://byoungd.github.io/up/threads/part-3/1-ai-learning" target="_blank" rel="noreferrer">AI 学习、项目开发与资源层创业</a> ｜ <a href="https://byoungd.github.io/up/templates/ai-task-brief" target="_blank" rel="noreferrer">AI 任务简报</a> ｜ <a href="https://byoungd.github.io/up/templates/learning-state" target="_blank" rel="noreferrer">学习状态</a> ｜ <a href="https://byoungd.github.io/up/templates/evidence-chain" target="_blank" rel="noreferrer">证据链模板</a></p><hr><p>来源：<a href="https://byoungd.github.io/up/templates/ai-learning-log" target="_blank" rel="noreferrer">人生进阶指南</a> · 稿件更新：2026-10-16。内容许可：<a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>。</p>',31)])])}const u=a(h,[["render",i]]);export{p as __pageData,u as default};
